import {useId} from 'react'
import {Layout} from '@github-ui/pacer/Layout'
import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {RepoAgentsView} from '../components/repo-agents-page/RepoAgentsView'
import {RepoAgentsSidebar} from '../components/repo-agents-page/RepoAgentsSidebar'
import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {useInitializeAuthToken} from '@github-ui/agent-sessions/hooks/use-initialize-auth-token'
import {useUpdateAppOffset} from '../hooks/use-update-app-offset'
import {repoAgentsRoute} from './repo-agents-route'
import {useHideFooter} from '@github-ui/use-hide-footer'

/**
 * Repository Agents landing page.
 * Displays agent sessions for a specific repository with task creation.
 */
export function RepoAgentsPage() {
  useUpdateAppOffset()
  const sidebarLabelId = useId()
  const {data: payload} = useRouteQuery(repoAgentsRoute, 'mainQuery')
  useHideFooter(true)

  useInitializeAuthToken(payload.initialAuthToken)

  return (
    <CurrentRepositoryProvider repository={payload.repository}>
      <ConsecutiveCAPI401sProvider>
        <Layout sidebarCondensable={false}>
          <Layout.Sidebar header={null} aria-labelledby={sidebarLabelId}>
            <RepoAgentsSidebar
              currentUserLogin={payload.currentUser?.login}
              copilotMemoryEnabled={payload.copilotMemoryEnabled}
              copilotSetupStepsFilePath={payload.copilotSetupStepsFilePath}
              copilotCodingAgentEnabled={payload.copilotCodingAgentEnabled}
            />
          </Layout.Sidebar>
          <Layout.ColumnLeft>
            <RepoAgentsView />
          </Layout.ColumnLeft>
        </Layout>
      </ConsecutiveCAPI401sProvider>
    </CurrentRepositoryProvider>
  )
}
