/* eslint-disable @github-ui/github-monorepo/restrict-relay-imports */
import type {ReactNode} from 'react'
import {CopilotChatProvider} from '@github-ui/copilot-chat/CopilotChatContext'
import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import type {ChatPayload} from '../routes/copilot-chat-payload-route-query'

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

export interface CopilotChatProvidersProps {
  children: ReactNode
  /**
   * Chat payload data required for CopilotChatProvider
   */
  chatPayload: ChatPayload
}

/**
 * Shared providers wrapper for components that need CopilotChat functionality.
 */
export function CopilotChatProviders({children, chatPayload}: CopilotChatProvidersProps) {
  return (
    <RelayEnvironmentProvider environment={environment}>
      <CopilotChatProvider
        workerPath={chatPayload.findFileWorkerPath}
        threadId={null}
        refs={chatPayload.refs ?? []}
        mode="assistive"
        ssoOrganizations={chatPayload.ssoOrganizations ?? []}
        copilotChatPayload={chatPayload}
      >
        {children}
      </CopilotChatProvider>
    </RelayEnvironmentProvider>
  )
}
