import {useQuery} from '@github-ui/react-query'
import type {PublicUser} from '@github-ui/agent-sessions/types/public-user'
import type {UnhydratedTask, OptimisticTask} from '@github-ui/agent-sessions/types/task'

export function useTaskCreators({
  tasks,
  initialData,
}: {
  tasks: Array<UnhydratedTask | OptimisticTask> | undefined
  initialData?: PublicUser[]
}) {
  const creatorIds = getCreatorIdsQueryString(tasks || [])
  return useQuery<PublicUser[]>({
    queryKey: ['task-creators', creatorIds],
    queryFn: async () => {
      if (creatorIds.length === 0) {
        return []
      }
      const response = await fetch(`/copilot/agent-sessions/users?user_ids=${encodeURIComponent(creatorIds)}`, {
        headers: {
          Accept: 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
        },
      })
      if (!response.ok) {
        throw new Error(`Failed to fetch task creators: ${response.status} ${response.statusText}`)
      }
      const data = await response.json()
      const users = data.users as PublicUser[]
      return users
    },
    initialData,
    enabled: creatorIds.length > 0,
  })
}

function getCreatorIdsQueryString(tasks: Array<UnhydratedTask | OptimisticTask>): string {
  const userIdSet = new Set<number>()
  for (const task of tasks) {
    if (task.creator_id !== undefined) {
      userIdSet.add(task.creator_id)
    }
  }
  return Array.from(userIdSet).join(',')
}
