import {Banner} from '@primer/react'
import {useArchiveDialog} from '../contexts/ArchiveDialogContext'

export function ArchiveTaskBanner() {
  const {archiveStatus, setArchiveStatus} = useArchiveDialog()

  const handleDismiss = () => {
    setArchiveStatus('idle')
  }

  if (archiveStatus === 'idle') {
    return null
  }

  if (archiveStatus === 'success') {
    return (
      <Banner
        variant="success"
        title="Session archived"
        hideTitle
        description="The session has been archived successfully."
        onDismiss={handleDismiss}
      />
    )
  }

  return (
    <Banner
      variant="critical"
      title="Archive failed"
      hideTitle
      description="Failed to archive the session. Please try again."
      onDismiss={handleDismiss}
    />
  )
}
