import {setTitle} from '@github-ui/document-metadata'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Heading} from '@primer/react'
import {useCallback, useEffect, useState} from 'react'
import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import {useSearchParams} from '@github-ui/use-navigate'
import {isFeatureEnabled} from '@github-ui/feature-flags'

import {CopilotDisclosure} from '@github-ui/agent-sessions/components/CopilotDisclosure'
import {NewTaskChatInput} from '@github-ui/agent-sessions/components/new-task-chat-input/NewTaskChatInput'
import {
  TaskCreationFailedBannerList,
  type FailedAPITaskCreationAttempt,
  getAPITaskParamsFromAttempt,
} from '@github-ui/agent-sessions/components/TaskCreationFailedBanner'
import type {DropdownRepository} from '@github-ui/agent-sessions/hooks/useCopilotRepoFetching'
import {useCreateAPITask} from '@github-ui/agent-sessions/hooks/use-create-api-task'
import type {CreateAPITaskMutationParams} from '@github-ui/agent-sessions/types/api-task'
import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import {AgentsBlankslate} from '@github-ui/agent-sessions/components/agents-view/AgentsBlankslate'

import {repoAgentsRoute} from '../../routes/repo-agents-route'
import {useRepoTasks, PAGE_SIZE} from '../../hooks/use-repo-tasks'
import {
  repoTasksQueryKey,
  type FetchRepoTasksResponse,
  setFlatTaskList,
  getFlatTaskList,
} from '@github-ui/agent-sessions/hooks/repo-task-utils'
import {CopilotChatProviders} from '../CopilotChatProviders'
import {RepoTaskList} from './RepoTaskList'
import {AgentIcebreakers} from '@github-ui/agent-sessions/components/agents-view/AgentIcebreakers'
import styles from './RepoAgentsView.module.css'
import type {IntentDetectionMode} from '@github-ui/agent-sessions/types/intent-detection-mode'
import {IntentDetectionProvider} from '@github-ui/agent-sessions/contexts/IntentDetectionContext'
import {useIcebreakers} from '@github-ui/agent-sessions/hooks/use-icebreakers'

export function RepoAgentsView() {
  const {data: payload} = useRouteQuery(repoAgentsRoute, 'mainQuery')
  const {
    repository,
    tasks: initialTasks,
    pullRequestMap: initialPullRequestsMap,
    currentUser,
    canCreateTasks,
    hasPaidCopilotAccess,
    memberRequestEntities,
    hasCEorCBAccess,
    icebreakerVariant,
  } = payload
  const {data: chatPayload} = useRouteQuery(repoAgentsRoute, 'copilotChatPayload')
  const [failedTaskCreationAttempts, setFailedTaskCreationAttempts] = useState<FailedAPITaskCreationAttempt[]>([])
  const [searchParams, setSearchParams] = useSearchParams()
  const decoupledModeEnabled = isFeatureEnabled('copilot_mission_control_decoupled_mode')

  // Get completed filter from query params and set initial active tab
  const completedFilter = searchParams.get('completed')
  const [activeTab, setActiveTab] = useState<'active' | 'completed'>(
    completedFilter === 'true' ? 'completed' : 'active',
  )

  // Get author filter from query params
  const authorFilter = searchParams.get('author')
  const isFilteredByCurrentUser = currentUser?.login ? authorFilter === currentUser.login : false

  const {tasks, isError, isLoading, isFetching, hasNextPage, counts} = useRepoTasks({
    owner: repository.ownerLogin,
    repo: repository.name,
    repoId: repository.id,
    currentUserId: isFilteredByCurrentUser ? currentUser?.id : undefined,
    initialData: initialTasks,
    initialPullRequestsMap,
    fetchArchivedTasks: activeTab === 'completed',
  })

  const {createTask} = useCreateAPITask<FetchRepoTasksResponse>({
    queryKey: repoTasksQueryKey(
      repository.ownerLogin,
      repository.name,
      isFilteredByCurrentUser ? currentUser?.id : undefined,
      1, // We will always add new tasks to page 1
      false, // We add new tasks to the open tasks list
    ),
    getFlatTaskList,
    setFlatTaskList,
    pageSize: PAGE_SIZE,
    onError: (error: Error, variables: CreateAPITaskMutationParams) => {
      setFailedTaskCreationAttempts(prev => [
        ...prev,
        {
          ...variables,
          errorMessage: error.message,
          timestamp: new Date().toISOString(),
        },
      ])
    },
    decoupledModeEnabled,
  })

  const {
    chatInputRef,
    textAreaRef,
    visible: icebreakersVisible,
    handleSelect: handleIcebreakerSelect,
    handleDismiss: handleIcebreakerDismiss,
    handleIcebreakerSubmit,
  } = useIcebreakers({enabled: decoupledModeEnabled, location: 'repo_agents', variant: icebreakerVariant})

  const handleUserSubmit = useCallback(
    async (
      content: string,
      selectedRepo: DropdownRepository | null,
      selectedBranch: string,
      selectedAgent: SelectedAgent,
      _selectedMode?: IntentDetectionMode,
      modelId?: string,
      createPullRequest?: boolean,
    ) => {
      handleIcebreakerSubmit(content)
      const trimmedContent = content.trim()
      if (trimmedContent === '') return
      if (!selectedRepo) return

      // Set page to 1 on new task creation and switch to open tab
      setActiveTab('active')
      setSearchParams(prev => {
        const next = new URLSearchParams(prev)
        next.delete('completed')
        next.delete('page')
        return next
      })

      // Create the task
      createTask({
        nwo: selectedRepo.nameWithOwner,
        problemStatement: trimmedContent,
        customAgent: selectedAgent?.subAgentSlug,
        agentId: selectedAgent?.topLevelAgentId,
        model: modelId,
        baseRef: selectedBranch || undefined,
        createPullRequest,
        eventType: 'repo_agents',
        intentDetectionMode: 'task', // For now we explicitly don't use intent detection on this path
      })
    },
    [handleIcebreakerSubmit, setSearchParams, createTask],
  )

  const handleRetry = (attemptIndex: number) => {
    const attempt = failedTaskCreationAttempts[attemptIndex]
    if (attempt) {
      setFailedTaskCreationAttempts(prev => prev.filter((_, index) => index !== attemptIndex))
      createTask(getAPITaskParamsFromAttempt(attempt))
    }
  }

  useEffect(() => {
    setTitle(`Agents · ${repository.nameWithOwner}`)
  }, [repository.nameWithOwner])

  // Show blankslate if user doesn't have a paid Copilot license (Pro/Business/Enterprise)
  if (isFeatureEnabled('repo_agents_show_upgrade_slate') && !hasPaidCopilotAccess) {
    return (
      <AgentsBlankslate
        hasCEorCBAccess={hasCEorCBAccess}
        memberRequestEntities={memberRequestEntities}
        location="repo_agents_blankslate"
      />
    )
  }

  return (
    <CurrentRepositoryProvider repository={repository}>
      <div className={styles.container} data-hpc>
        <div className={styles.content}>
          <header className={styles.header}>
            <Heading as="h2" className={styles.title}>
              Sessions
            </Heading>
          </header>
          {canCreateTasks && (
            <CopilotChatProviders chatPayload={chatPayload}>
              <IntentDetectionProvider>
                <div className={styles.taskForm}>
                  <NewTaskChatInput
                    handleUserSubmit={handleUserSubmit}
                    initialRepo={repository}
                    hideRepoSelector
                    isNewConversation
                    decoupledModeEnabled={decoupledModeEnabled}
                    chatInputRef={chatInputRef}
                    textAreaRef={textAreaRef}
                  />
                </div>
                {icebreakersVisible && (
                  <AgentIcebreakers
                    onSelect={handleIcebreakerSelect}
                    onDismiss={handleIcebreakerDismiss}
                    location="repo_agents"
                    variant={icebreakerVariant}
                  />
                )}
              </IntentDetectionProvider>
            </CopilotChatProviders>
          )}
          <TaskCreationFailedBannerList
            attempts={failedTaskCreationAttempts}
            onRetry={handleRetry}
            onDismiss={index => setFailedTaskCreationAttempts(prev => prev.filter((_, i) => i !== index))}
          />
          <RepoTaskList
            tasks={tasks}
            isError={isError}
            isLoading={isLoading}
            isFetching={isFetching}
            activeTab={activeTab}
            setActiveTab={setActiveTab}
            hasNextPage={hasNextPage}
            openCount={counts?.open}
            closedCount={counts?.closed}
          />
          <CopilotDisclosure />
        </div>
      </div>
    </CurrentRepositoryProvider>
  )
}
