import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {repoAgentsAppBuilder} from './config/app-builder'

import {repoAgentsRoute} from './routes/repo-agents-route'
import {RepoAgentsPage} from './routes/RepoAgentsPage'

import {repoTaskRoute, repoTaskByIdRoute} from './routes/task-route'
import {TaskSuspended} from './routes/Task'

// eslint-disable-next-line primer-react/enforce-css-module-default-import
import './repo-agents.module.css'

/**
 * Create the DataRouter app from route configurations.
 */
export const repoAgentsApp = repoAgentsAppBuilder.createDataRouterAppFromRoutes([
  repoAgentsRoute.toRoute({Component: RepoAgentsPage}),
  repoTaskRoute.toRoute({Component: TaskSuspended}),
  repoTaskByIdRoute.toRoute({Component: TaskSuspended}),
])

registerDataRouterApp(repoAgentsApp)
