import {mainQuery} from '@github-ui/react-core/future/main-query'
import {repoAgentsAppBuilder} from '../config/app-builder'
import type {RepoTaskPayload} from '../types/repo-agents-payload'
import {copilotChatPayloadRouteQuery} from './copilot-chat-payload-route-query'

/**
 * Task detail page route configuration (pull-based URL).
 */
export const repoTaskRoute = repoAgentsAppBuilder.createQueryRouteConfig('repoTaskRoute', {
  path: '/:owner/:repo/agents/pull/:pullNumber',
  queries: [mainQuery<RepoTaskPayload>(), copilotChatPayloadRouteQuery],
})

/**
 * Task detail page route configuration (Task ID-based URL).
 */
export const repoTaskByIdRoute = repoAgentsAppBuilder.createQueryRouteConfig('repoTaskByIdRoute', {
  path: '/:owner/:repo/tasks/:taskId',
  queries: [mainQuery<RepoTaskPayload>(), copilotChatPayloadRouteQuery],
})
