import {Fragment} from 'react'
import {Heading} from '@primer/react'
import {PlusIcon} from '@primer/octicons-react'
import {SidebarSection} from '@github-ui/pacer/SidebarNavigation'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'
import {useLocation} from '@github-ui/react-router'
import {useSearchParams} from '@github-ui/use-navigate'
import type {Repository} from '@github-ui/current-repository'
import {
  getTaskSecondaryText,
  groupTasksByUpdatedAt,
  TaskBucketHeader,
  TaskListEntry,
} from '@github-ui/agent-sessions/components/TaskList'
import {NewRepoAgentTaskButton} from '@github-ui/new-repo-agent-task-button/NewRepoAgentTaskButton'
import {useRepoTasks} from '../hooks/use-repo-tasks'
import {getTaskUrl} from '../utils/url-helpers'
import styles from './TaskSidebar.module.css'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export interface TaskSidebarProps {
  repository: Repository
  currentUserId?: number
  /**
   * The current user's login, used to determine if tasks should be filtered.
   * When provided, tasks are filtered to the current user by default (when no author param).
   */
  currentUserLogin?: string
  /**
   * Whether the current user can push changes (i.e. write) to the repo.
   */
  currentUserCanPush?: boolean
  /**
   * ID to apply to the sidebar heading for accessibility labeling.
   */
  labelId?: string
}

/**
 * TaskSidebar component showing task list for the current repository.
 * Defaults to showing only the current user's sessions. Only shows all sessions
 * when the author query parameter is explicitly set to a different user or '*'.
 */
export function TaskSidebar({
  repository,
  currentUserId,
  currentUserLogin,
  currentUserCanPush,
  labelId,
}: TaskSidebarProps) {
  const decoupledModeEnabled = isFeatureEnabled('copilot_mission_control_decoupled_mode')

  return (
    <>
      <div className={styles.header}>
        <Heading as="h2" id={labelId} className={styles.heading}>
          Agents
        </Heading>
        {currentUserCanPush && (
          <NewRepoAgentTaskButton
            repository={repository}
            currentUserId={currentUserId}
            currentUserLogin={currentUserLogin}
            eventType="repo_agents_sidebar"
            size="small"
            label="New session"
            icon={PlusIcon}
            variant="invisible"
            decoupledModeEnabled={decoupledModeEnabled}
          />
        )}
      </div>
      <SidebarContent
        owner={repository.ownerLogin}
        repo={repository.name}
        repoId={repository.id}
        currentUserId={currentUserId}
        currentUserLogin={currentUserLogin}
      />
    </>
  )
}

interface SidebarContentProps {
  owner: string
  repo: string
  repoId: number
  currentUserId?: number
  currentUserLogin?: string
}

function SidebarContent({owner, repo, repoId, currentUserId, currentUserLogin}: SidebarContentProps) {
  const location = useLocation()
  const {sidebarExpanded, toggleSidebar} = useLayoutContext()
  const [searchParams] = useSearchParams()

  // Create a copy of searchParams without session_id - it should not persist when navigating between tasks
  const filteredParams = new URLSearchParams(searchParams)
  filteredParams.delete('session_id')
  const searchParamsString = filteredParams.toString()

  // Get author filter from query params - filter by currentUserId if author matches currentUserLogin,
  // or if no author param is present (since we default to showing the user's own sessions)
  const authorFilter = searchParams.get('author')
  const isFilteredByCurrentUser = currentUserLogin ? authorFilter === currentUserLogin || authorFilter === null : false

  const {tasks, isLoading, isError} = useRepoTasks({
    owner,
    repo,
    repoId,
    currentUserId: isFilteredByCurrentUser ? currentUserId : undefined,
  })

  const handleTaskClick = () => {
    if (sidebarExpanded) {
      toggleSidebar()
    }
  }

  const groupedTasks = groupTasksByUpdatedAt(tasks)

  if (isError) {
    return <div className={styles.errorMessage}>Failed to load sessions</div>
  }

  if (!isLoading && tasks.length === 0) {
    return <div className={styles.emptyMessage}>No active sessions</div>
  }

  return (
    <SidebarSection isLoading={isLoading} isEmpty={tasks.length === 0}>
      {groupedTasks.map(bucket => (
        <Fragment key={bucket.label}>
          <TaskBucketHeader label={bucket.label} />
          {bucket.tasks.map(task => {
            const basePath = getTaskUrl(`${owner}/${repo}`, task) ?? ''
            const taskUrl = searchParamsString ? `${basePath}?${searchParamsString}` : basePath
            const isSelected = location.pathname === basePath

            return (
              <TaskListEntry
                key={task.resource_id}
                task={task}
                href={taskUrl}
                isSelected={isSelected}
                secondaryText={getTaskSecondaryText(task)}
                onTaskClick={handleTaskClick}
                reloadDocument={false}
                repoOwner={owner}
                repoName={repo}
                currentUserIsOwner={currentUserId === task.creator_id}
              />
            )
          })}
        </Fragment>
      ))}
    </SidebarSection>
  )
}
