import type {UITask} from '@github-ui/agent-sessions/types/task'
import {isTaskFromCLI} from '@github-ui/agent-sessions/utils/cli'
import {getLeadingVisualIconAttributes} from '@github-ui/agent-sessions/utils/get-leading-visual-icon-attributes'
import {getTaskTitle} from '@github-ui/agent-sessions/utils/task-helpers'

import {WithShimmerEffect} from '@github-ui/copilot-chat/components/WithShimmerEffect'
import {useAgentInfo} from '@github-ui/agent-sessions/hooks/use-agent-info'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {DiffStats} from '@github-ui/diffs/DiffStats'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {DotFillIcon, GitPullRequestIcon} from '@primer/octicons-react'
import {RelativeTime} from '@primer/react'
import {clsx} from 'clsx'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import {getTaskUrl} from '../../utils/url-helpers'
import {ListItemTitle} from './ListParts'
import styles from './RepoTaskListItem.module.css'

interface RepoTaskListItemProps {
  task: UITask
  nwo: string
  onTitleClick?: () => void
}

export function RepoTaskListItem({task, nwo, onTitleClick}: RepoTaskListItemProps) {
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const {latest_session_state: state, archived_at} = task
  const title = getTaskTitle(task, task.pull?.title)
  const baseTaskUrl = getTaskUrl(nwo, task)
  // Preserve only the author filter when navigating to a task
  const authorParam = searchParams.get('author')
  const taskUrl = baseTaskUrl && authorParam ? `${baseTaskUrl}?author=${encodeURIComponent(authorParam)}` : baseTaskUrl
  const prState = task.pull?.state ?? 'open'
  const prInMergeQueue = task.pull?.inMergeQueue ?? false
  const isCLI = isTaskFromCLI(task)

  const leadingVisualAttributes = task.isOptimistic
    ? {icon: DotFillIcon, color: 'var(--fgColor-attention)'}
    : getLeadingVisualIconAttributes(prState, prInMergeQueue, state, !!archived_at, isCLI)

  const {data: agentInfo} = useAgentInfo(task.agentId ? Number(task.agentId) : undefined)

  const handleTitleClick = (e: React.MouseEvent) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if (!taskUrl || e.metaKey || e.ctrlKey) {
      return
    }

    e.preventDefault()
    onTitleClick?.()
    navigate(taskUrl)
  }

  const renderDescriptionText = () => {
    if (task.isOptimistic) {
      return `Initializing session...`
    }

    return (
      <>
        {task.creator_login} created <RelativeTime format="relative" datetime={task.latest_session_updated_at} />
      </>
    )
  }

  return (
    <SimpleListItem className={clsx(styles.item, task.isOptimistic && styles.optimisticItem)}>
      <SimpleListItem.LeadingVisual className={styles.itemLeadingVisual}>
        {leadingVisualAttributes.icon && (
          <div
            style={{
              color: leadingVisualAttributes.color,
              marginTop: state === 'in_progress' && !task.isOptimistic && !isCLI ? '3px' : '1px',
            }}
          >
            <leadingVisualAttributes.icon />
          </div>
        )}
      </SimpleListItem.LeadingVisual>
      {task.isOptimistic ? (
        <WithShimmerEffect className={styles.shimmeringTitle} innerClassName="d-flex">
          <ListItemTitle as="div">{title}</ListItemTitle>
        </WithShimmerEffect>
      ) : (
        <ListItemTitle onClick={handleTitleClick} as="a" href={taskUrl}>
          {title}
        </ListItemTitle>
      )}
      <SimpleListItem.Description className={styles.itemDescription}>
        {renderDescriptionText()}
      </SimpleListItem.Description>
      <SimpleListItem.Actions className={styles.itemActions}>
        <div className={styles.prNumberButtonContainer}>
          {!task.isOptimistic && task.pull && (
            <a
              className={styles.prNumberButton}
              href={task.pull.url}
              aria-label={`View pull request #${task.pull.number}`}
            >
              <GitPullRequestIcon />#{task.pull.number}
            </a>
          )}
        </div>
        <div className={styles.diffStatsContainer}>
          {state !== 'in_progress' && task.pull?.pr_diff_summary && (
            <DiffStats
              linesAdded={task.pull.pr_diff_summary.lines_added}
              linesChanged={task.pull.pr_diff_summary.lines_changed}
              linesDeleted={task.pull.pr_diff_summary.lines_deleted}
            />
          )}
        </div>
        <div className={styles.agentAvatarTrailingVisual}>
          {agentInfo?.avatar_url && (
            <GitHubAvatar src={agentInfo?.avatar_url} size={16} square alt={agentInfo?.display_name || 'Agent'} />
          )}
        </div>
      </SimpleListItem.Actions>
    </SimpleListItem>
  )
}
