/**
 * Generates the URL for a repository agent pull request page
 * @param repositoryNwo - Repository name with owner (e.g., "github/github")
 * @param pullNumber - Pull request number
 * @returns URL path for the repo agent pull page
 */
export function repoAgentTaskUrl(repositoryNwo: string, pullNumber: number): string {
  const [owner, repo] = repositoryNwo.split('/')
  return `/${owner}/${repo}/agents/pull/${pullNumber}`
}

/**
 * Generates the URL for a repository agent task page based on task ID (new API)
 * @param repositoryNwo - Repository name with owner (e.g., "github/github")
 * @param taskId - Task ID
 * @returns URL path for the repo agent task page
 */
export function repoAgentTaskUrlById(repositoryNwo: string, taskId: string): string {
  const [owner, repo] = repositoryNwo.split('/')
  return `/${owner}/${repo}/tasks/${taskId}`
}

/**
 * Generates the appropriate URL for a task based on available identifiers.
 * Prefers task ID if available, falls back to pull request number.
 * @param repositoryNwo - Repository name with owner (e.g., "github/github")
 * @param task - Object containing optional task id and pull request info
 * @returns URL path for the task, or undefined if no identifiers available
 */
export function getTaskUrl(
  repositoryNwo: string,
  task: {id?: string | null; pull?: {number: number} | null},
): string | undefined {
  if (task.id) {
    return repoAgentTaskUrlById(repositoryNwo, task.id)
  }

  if (task.pull) {
    return repoAgentTaskUrl(repositoryNwo, task.pull.number)
  }

  return undefined
}
