import {AlertIcon} from '@primer/octicons-react'
import {Pagination} from '@primer/react'
import {useSearchParams} from '@github-ui/use-navigate'
import type {MouseEvent} from 'react'
import {useState} from 'react'
import type {UITask} from '@github-ui/agent-sessions/types/task'
import {ListViewSectionFilterLink} from '@github-ui/list-view/ListViewSectionFilterLink'
import {SimpleListView} from '@github-ui/simple-list-view'
import {SimpleListHeader} from '@github-ui/simple-list-view/SimpleListHeader'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {RepoTaskListItem} from './RepoTaskListItem'
import {ListItemsSkeletonLoader} from './ListParts'
import {useCurrentRepository} from '@github-ui/current-repository'
import styles from './RepoTaskList.module.css'
import {Blankslate} from '@primer/react/experimental'
import {clsx} from 'clsx'
import {parsePageNumber} from '@github-ui/agent-sessions/utils/url-helpers'

function RepoTaskListPagination({hasNextPage}: {hasNextPage: boolean}) {
  const [searchParams, setSearchParams] = useSearchParams()
  const currentPage = parsePageNumber(searchParams.get('page'))
  const hasPreviousPage = currentPage > 1
  // Workaround until we return total task count from the tasks API
  const pageCount = hasNextPage ? currentPage + 1 : currentPage

  const onPageChange = (e: MouseEvent, page: number): void => {
    e.preventDefault()
    searchParams.set('page', page.toString())
    setSearchParams(searchParams)
  }

  if (!hasNextPage && !hasPreviousPage) return <></>
  return <Pagination showPages={false} pageCount={pageCount} currentPage={currentPage} onPageChange={onPageChange} />
}

interface RepoTaskListProps {
  tasks: UITask[]
  isError: boolean
  isLoading: boolean
  isFetching: boolean
  activeTab: 'active' | 'completed'
  setActiveTab: (tab: 'active' | 'completed') => void
  hasNextPage: boolean
  openCount?: number
  closedCount?: number
}

export function RepoTaskList({
  tasks,
  isError,
  isLoading,
  isFetching,
  activeTab,
  setActiveTab,
  hasNextPage,
  openCount,
  closedCount,
}: RepoTaskListProps) {
  const [searchParams, setSearchParams] = useSearchParams()
  const repo = useCurrentRepository()
  const nwo = `${repo.ownerLogin}/${repo.name}`

  // Track page/tab/author to detect navigation vs optimistic updates
  const currentPage = parsePageNumber(searchParams.get('page'))
  const currentAuthor = searchParams.get('author')
  const [prevPage, setPrevPage] = useState(currentPage)
  const [prevTab, setPrevTab] = useState(activeTab)
  const [prevAuthor, setPrevAuthor] = useState(currentAuthor)

  // Detect navigation by comparing current and previous values
  const isNavigating = prevPage !== currentPage || prevTab !== activeTab || prevAuthor !== currentAuthor

  // Update previous values only when fetching completes
  if (!isFetching && isNavigating) {
    setPrevPage(currentPage)
    setPrevTab(activeTab)
    setPrevAuthor(currentAuthor)
  }

  const hasNoSessions = openCount === 0 && closedCount === 0
  const emptyTitle = hasNoSessions
    ? 'There are no sessions yet'
    : activeTab === 'active'
      ? 'There are no active sessions'
      : 'There are no completed sessions'

  // Only show skeletons when navigating (page/tab change), not for optimistic updates
  const showSkeletonLoaders = (isFetching && isNavigating) || isLoading

  return (
    <div className={styles.list}>
      <SimpleListView>
        <SimpleListHeader className={styles.header}>
          <SimpleListHeader.Metadata>
            <ul className={clsx(styles.tabsContainer, 'list-style-none')}>
              <li>
                <ListViewSectionFilterLink
                  title="Active"
                  isSelected={activeTab === 'active'}
                  count={openCount}
                  isLoading={showSkeletonLoaders}
                  href="#"
                  onClick={e => {
                    e.preventDefault()
                    setActiveTab('active')
                    searchParams.delete('page')
                    searchParams.delete('completed')
                    setSearchParams(searchParams)
                  }}
                />
              </li>
              <li>
                <ListViewSectionFilterLink
                  title="Completed"
                  isSelected={activeTab === 'completed'}
                  count={closedCount}
                  isLoading={showSkeletonLoaders}
                  href="#"
                  onClick={e => {
                    e.preventDefault()
                    setActiveTab('completed')
                    searchParams.delete('page')
                    searchParams.set('completed', 'true')
                    setSearchParams(searchParams)
                  }}
                />
              </li>
            </ul>
          </SimpleListHeader.Metadata>
        </SimpleListHeader>
        {tasks.length === 0 && !isError && !isLoading ? (
          <Blankslate className={styles.listContainer}>
            <Blankslate.Heading>{emptyTitle}</Blankslate.Heading>
            <Blankslate.Description>
              Let agents work independently in the background to complete tasks, and then monitor their progress.
            </Blankslate.Description>
          </Blankslate>
        ) : (
          <SimpleListView.Items className={clsx(styles.listContainer, styles.items)}>
            {isError ? (
              <SimpleListItem className={styles.emptyItem}>
                <AlertIcon className={styles.noItemsIcon} />
                <p className={styles.emptyTitle}>Unable to load tasks, try again later.</p>
              </SimpleListItem>
            ) : showSkeletonLoaders ? (
              <ListItemsSkeletonLoader />
            ) : (
              <>
                {tasks.map(task => (
                  <RepoTaskListItem key={task.clientGeneratedId ?? task.id ?? task.resource_id} task={task} nwo={nwo} />
                ))}
              </>
            )}
          </SimpleListView.Items>
        )}
      </SimpleListView>
      <RepoTaskListPagination hasNextPage={hasNextPage} />
    </div>
  )
}
