import {useCallback, useId} from 'react'
import styles from './Task.module.css'
import {CurrentUserProvider} from '@github-ui/agent-sessions/contexts/CurrentUserContext'
import {TaskChat} from '@github-ui/agent-sessions/components/task-view/TaskChat'
import {useSessions} from '@github-ui/agent-sessions/hooks/useSessions'
import {usePullRequest} from '@github-ui/agent-sessions/hooks/usePullRequest'
import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {PullContextProvider} from '@github-ui/agent-sessions/contexts/PullContext'
import {useInitializeAuthToken} from '@github-ui/agent-sessions/hooks/use-initialize-auth-token'
import {ArchiveDialogProvider} from '@github-ui/agent-sessions/contexts/ArchiveDialogContext'
import {ArchiveConfirmationDialog} from '@github-ui/agent-sessions/components/ArchiveConfirmationDialog'
import {ArchiveTaskBanner} from '@github-ui/agent-sessions/components/ArchiveTaskBanner'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import type {ChatPayload} from './copilot-chat-payload-route-query'
import {CopilotChatProviders} from '../components/CopilotChatProviders'
import type {RepoTaskPayload} from '../types/repo-agents-payload'
import {CurrentRepositoryProvider, useCurrentRepository} from '@github-ui/current-repository'
import {TaskSidebar} from '../components/TaskSidebar'
import {Layout} from '@github-ui/pacer/Layout'
import {useUpdateAppOffset} from '../hooks/use-update-app-offset'
import {useLoaderData} from '@github-ui/react-router'
import {useHideFooter} from '@github-ui/use-hide-footer'
import {IntentDetectionProvider} from '@github-ui/agent-sessions/contexts/IntentDetectionContext'
import {ChatStreamProvider} from '@github-ui/agent-sessions/contexts/ChatStreamContext'
import {useIntentDetection} from '@github-ui/agent-sessions/hooks/useIntentDetection'
import {useNavigableRef} from '@github-ui/navigable-ref'
import {
  ContentPreviewProvider,
  useContentPreview,
  useContentPreviewOpen,
} from '@github-ui/copilot-immersive-v1/components/ContentPreview/ContentPreviewContext'
import {ContentPreview} from '@github-ui/copilot-immersive-v1/components/ContentPreview/ContentPreview'

export function TaskSuspended() {
  const {route: currentRoute} = useLoaderData()
  const {data: payload} = useRouteQuery(currentRoute, 'mainQuery')
  const {data: chatPayload} = useRouteQuery(currentRoute, 'copilotChatPayload')
  const sidebarLabelId = useId()
  useUpdateAppOffset()
  useHideFooter(true)

  useInitializeAuthToken(payload.initialAuthToken)

  return (
    <CurrentRepositoryProvider repository={payload.repository}>
      <ConsecutiveCAPI401sProvider>
        <ArchiveDialogProvider>
          <IntentDetectionProvider>
            <ChatStreamProvider>
              <CopilotChatProviders chatPayload={chatPayload}>
                <ContentPreviewProvider>
                  <ArchiveTaskBanner />
                  <TaskLayout payload={payload} chatPayload={chatPayload} sidebarLabelId={sidebarLabelId} />
                  <ArchiveConfirmationDialog />
                </ContentPreviewProvider>
              </CopilotChatProviders>
            </ChatStreamProvider>
          </IntentDetectionProvider>
        </ArchiveDialogProvider>
      </ConsecutiveCAPI401sProvider>
    </CurrentRepositoryProvider>
  )
}

interface TaskLayoutProps {
  payload: RepoTaskPayload
  chatPayload: ChatPayload
  sidebarLabelId: string
}

// This is extracted largely just so we can use the necessary
// preview hooks inside the necessary provider.
function TaskLayout({payload, chatPayload, sidebarLabelId}: TaskLayoutProps) {
  const {isUsingIntentDetection} = useIntentDetection()
  const ref = useNavigableRef<HTMLTextAreaElement>()

  const isContentPreviewOpen = useContentPreviewOpen()
  const {openPreviewPane, closePreviewPane} = useContentPreview()

  const setContentPreviewPaneOpen = useCallback(
    (open: boolean) => {
      if (open) {
        openPreviewPane()
      } else {
        closePreviewPane()
      }
    },
    [openPreviewPane, closePreviewPane],
  )

  return (
    <Layout sidebarCondensable={false} secondaryColumnState={[isContentPreviewOpen, setContentPreviewPaneOpen]}>
      <Layout.Sidebar
        header={null}
        aria-labelledby={sidebarLabelId}
        className={styles.sidebar}
        innerClassName={styles.sidebarInner}
      >
        <TaskSidebar
          repository={payload.repository}
          currentUserId={payload.currentUser?.id}
          currentUserLogin={payload.currentUser?.login}
          currentUserCanPush={payload.currentUserCanPush}
          labelId={sidebarLabelId}
        />
      </Layout.Sidebar>
      <Layout.ColumnLeft>
        <Task payload={payload} chatPayload={chatPayload} />
      </Layout.ColumnLeft>
      {isUsingIntentDetection && (
        <Layout.ColumnRight>
          <ContentPreview returnFocusRef={ref} />
        </Layout.ColumnRight>
      )}
    </Layout>
  )
}

interface TaskProps {
  payload: RepoTaskPayload
  chatPayload: ChatPayload
}

/**
 * Task detail page component.
 */
export function Task({payload, chatPayload}: TaskProps) {
  const {pull, task, sessions, currentUser, branchAliveChannel} = payload
  const repo = useCurrentRepository()

  // Fetch sessions data - use initial data from the app payload to avoid an extra fetch
  const {data: currentSessions} = useSessions({
    pullId: pull?.id,
    taskId: payload.taskId,
    initialData: sessions,
    sessionsPollingInterval: 0,
  })

  // Fetch PR data
  const {data: fetchedPull} = usePullRequest({
    pullRequestId: pull?.id,
    includeBody: false,
    initialData: pull,
    // Immediately refetch to get full PR data with diff stats
    refetchOnMount: true,
  })

  const currentUserIsSessionOwner = !!(currentUser?.id === currentSessions?.[0]?.user_id)

  // Preserve the route task ID so TaskChat can recover from a taskId-only initial payload.
  const taskId = payload.taskId ?? currentSessions?.[0]?.task_id

  return (
    <CurrentUserProvider
      currentUser={currentUser}
      currentUserIsSessionOwner={currentUserIsSessionOwner}
      optedInToFeedback={chatPayload.optedInToUserFeedback}
    >
      <PullContextProvider pull={fetchedPull}>
        <div className={styles.container} data-hpc>
          <CopilotChatProviders chatPayload={chatPayload}>
            <TaskChat
              key={taskId ?? payload.taskId}
              {...payload}
              showHeader
              isRepoAgentsView
              repoOwner={repo.ownerLogin}
              repoName={repo.name}
              taskId={taskId}
              branchAliveChannel={branchAliveChannel}
              task={task}
            />
          </CopilotChatProviders>
        </div>
      </PullContextProvider>
    </CurrentUserProvider>
  )
}
